<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ISPAGENDA – Inspektorat Daerah Kabupaten Brebes</title>
<link rel="icon" href="{{ asset('favicon.ico') }}" />
<link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800;1,400&family=Playfair+Display:wght@700;800;900&display=swap" rel="stylesheet">
<style>
  :root {
    --primary: #FFC107;
    --primary-dark: #E5AC00;
    --primary-light: #FFD54F;
    --dark: #1A1A1B;
    --surface: #FFFFFF;
    --bg: #F8F9FA;
    --text-muted: #6B7280;
    --border: rgba(26,26,27,0.08);
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    font-family: 'Plus Jakarta Sans', sans-serif;
    background: var(--bg);
    color: var(--dark);
    min-height: 100vh;
    overflow-x: hidden;
  }

  /* TOP BAR */
  .topbar {
    background: var(--dark);
    color: rgba(255,255,255,0.55);
    font-size: 11.5px;
    font-weight: 500;
    padding: 8px 40px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    letter-spacing: 0.4px;
  }
  .topbar-left { display: flex; align-items: center; gap: 8px; }
  .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--primary); display: inline-block; animation: pulse 2s infinite; }
  @keyframes pulse { 0%,100% { opacity:1; } 50% { opacity:0.4; } }

  /* HEADER */
  .header {
    background: var(--surface);
    border-bottom: 3px solid var(--primary);
    padding: 12px 40px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: 0 2px 24px rgba(0,0,0,0.07);
  }
  .header-brand { display: flex; align-items: center; gap: 14px; }
  .header-brand img.logo-brebes { height: 52px; width: auto; }
  .header-brand img.logo-insp { height: 42px; width: auto; }
  .header-divider { width: 1px; height: 40px; background: var(--border); }
  .header-text h1 {
    font-size: 12.5px; font-weight: 800; color: var(--dark);
    line-height: 1.3; text-transform: uppercase; letter-spacing: 0.4px;
  }
  .header-text p { font-size: 10.5px; color: var(--text-muted); font-weight: 400; margin-top: 2px; }
  .header-badge {
    display: flex; align-items: center; gap: 7px;
    background: var(--primary); color: var(--dark);
    font-size: 11px; font-weight: 800; padding: 7px 16px;
    border-radius: 3px; letter-spacing: 1px; text-transform: uppercase;
  }

  /* HERO SPLIT */
  .hero {
    display: grid;
    grid-template-columns: 1fr 390px;
    min-height: calc(100vh - 116px);
  }

  /* LEFT PANEL */
  .hero-left { position: relative; overflow: hidden; }
  .hero-left-bg {
    position: absolute; inset: 0;
    background-image: url('data:image/jpeg;base64,');
    background-size: cover;
    background-position: center 25%;
    transform: scale(1.06);
    animation: slowZoom 12s ease forwards;
  }
  @keyframes slowZoom { to { transform: scale(1); } }
  .hero-left-overlay {
    position: absolute; inset: 0;
    background: linear-gradient(
      150deg,
      rgba(26,26,27,0.88) 0%,
      rgba(26,26,27,0.65) 45%,
      rgba(255,193,7,0.12) 100%
    );
  }
  .hero-left-overlay::after {
    content: '';
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 220px;
    background: linear-gradient(to top, rgba(26,26,27,0.95), transparent);
  }

  /* Gold geometric accent */
  .hero-accent {
    position: absolute;
    top: 0; right: 0;
    width: 180px; height: 180px;
    border-bottom-left-radius: 100%;
    background: linear-gradient(135deg, rgba(255,193,7,0.15), transparent);
    pointer-events: none;
  }

  .hero-left-content {
    position: relative; z-index: 2;
    padding: 56px 56px 100px;
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: center;
  }

  .hero-label {
    display: inline-flex; align-items: center; gap: 8px;
    background: var(--primary); color: var(--dark);
    font-size: 10.5px; font-weight: 800;
    padding: 5px 14px; border-radius: 2px;
    text-transform: uppercase; letter-spacing: 2px;
    margin-bottom: 24px; width: fit-content;
    opacity: 0; animation: fadeUp 0.6s 0.1s forwards;
  }
  .hero-subtitle {
    font-size: 12px; font-weight: 600;
    color: rgba(255,255,255,0.55); letter-spacing: 3.5px;
    text-transform: uppercase; margin-bottom: 20px;
    opacity: 0; animation: fadeUp 0.6s 0.25s forwards;
  }
  .hero-title {
    font-family: 'Playfair Display', serif;
    font-size: clamp(32px, 4vw, 52px);
    font-weight: 900; color: #fff;
    line-height: 1.12; margin-bottom: 28px;
    opacity: 0; animation: fadeUp 0.7s 0.35s forwards;
  }
  .hero-title .highlight { color: var(--primary); }
  .hero-title .sub {
    display: block;
    font-size: clamp(18px, 2.2vw, 27px);
    font-weight: 700; color: rgba(255,255,255,0.75);
    margin-top: 6px; font-style: italic;
    letter-spacing: 0.5px;
  }

  .hero-taglines {
    display: flex; flex-wrap: wrap; gap: 8px;
    margin-bottom: 32px;
    opacity: 0; animation: fadeUp 0.6s 0.5s forwards;
  }
  .tagline-pill {
    background: rgba(255,255,255,0.07);
    border: 1px solid rgba(255,255,255,0.15);
    color: rgba(255,255,255,0.75);
    font-size: 11px; font-weight: 600;
    padding: 5px 14px; border-radius: 20px;
    letter-spacing: 0.5px;
    transition: all 0.4s ease;
  }
  .tagline-pill.active {
    background: rgba(255,193,7,0.18);
    border-color: rgba(255,193,7,0.5);
    color: var(--primary-light);
  }

  .hero-desc {
    font-size: 14.5px; color: rgba(255,255,255,0.68);
    line-height: 1.8; max-width: 540px; margin-bottom: 40px;
    opacity: 0; animation: fadeUp 0.6s 0.65s forwards;
  }

  .hero-actions {
    display: flex; gap: 12px; flex-wrap: wrap;
    opacity: 0; animation: fadeUp 0.6s 0.8s forwards;
  }
  .btn {
    display: inline-flex; align-items: center; gap: 9px;
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-size: 13px; font-weight: 700;
    padding: 13px 26px; border-radius: 3px;
    cursor: pointer; text-decoration: none;
    transition: all 0.22s ease; letter-spacing: 0.2px;
    border: 2px solid transparent;
  }
  .btn-primary {
    background: var(--primary); color: var(--dark);
    border-color: var(--primary);
  }
  .btn-primary:hover {
    background: var(--primary-dark); border-color: var(--primary-dark);
    transform: translateY(-2px); box-shadow: 0 8px 28px rgba(255,193,7,0.45);
  }
  .btn-outline {
    background: transparent; color: #fff;
    border-color: rgba(255,255,255,0.3);
    backdrop-filter: blur(8px);
  }
  .btn-outline:hover {
    background: rgba(255,255,255,0.1);
    border-color: rgba(255,255,255,0.65);
    transform: translateY(-2px);
  }
  .btn svg { width: 15px; height: 15px; flex-shrink: 0; }

  /* STATS BAR */
  .stats-bar {
    position: absolute;
    bottom: 32px; left: 56px; right: 56px;
    display: flex; gap: 0;
    z-index: 3;
    opacity: 0; animation: fadeUp 0.6s 1.1s forwards;
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 6px; backdrop-filter: blur(10px);
    overflow: hidden;
  }
  .stat-item {
    flex: 1; padding: 14px 20px;
    display: flex; flex-direction: column;
    align-items: center;
    border-right: 1px solid rgba(255,255,255,0.07);
  }
  .stat-item:last-child { border-right: none; }
  .stat-num {
    font-family: 'Playfair Display', serif;
    font-size: 24px; font-weight: 800;
    color: var(--primary); line-height: 1;
  }
  .stat-label {
    font-size: 9.5px; color: rgba(255,255,255,0.4);
    font-weight: 600; margin-top: 3px;
    text-transform: uppercase; letter-spacing: 1px;
    text-align: center;
  }

  /* RIGHT PANEL */
  .hero-right {
    background: var(--surface);
    border-left: 1px solid var(--border);
    display: flex; flex-direction: column;
    overflow-y: auto;
  }
  .right-header {
    padding: 28px 28px 18px;
    border-bottom: 1px solid var(--border);
    background: var(--surface);
    position: sticky; top: 0; z-index: 10;
  }
  .right-header-label {
    font-size: 9.5px; font-weight: 800;
    text-transform: uppercase; letter-spacing: 2.5px;
    color: var(--primary-dark); margin-bottom: 5px;
    display: flex; align-items: center; gap: 6px;
  }
  .right-header-label::before {
    content: '';
    width: 16px; height: 2px; background: var(--primary);
    border-radius: 1px;
  }
  .right-header h2 {
    font-size: 20px; font-weight: 800; color: var(--dark);
  }
  .right-header p {
    font-size: 12px; color: var(--text-muted); margin-top: 3px;
  }

  .portal-grid {
    padding: 20px 24px;
    display: flex; flex-direction: column;
    gap: 9px; flex: 1;
  }
  .portal-row { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; }

  .portal-card {
    display: flex; flex-direction: column;
    align-items: flex-start;
    padding: 16px 18px;
    background: var(--bg);
    border: 1.5px solid var(--border);
    border-radius: 8px;
    text-decoration: none;
    transition: all 0.22s ease;
    position: relative; overflow: hidden;
    cursor: pointer; gap: 9px;
    opacity: 0; transform: translateY(14px);
  }
  .portal-card.visible { opacity: 1; transform: translateY(0); }
  .portal-card::before {
    content: '';
    position: absolute;
    left: 0; top: 0; bottom: 0;
    width: 3px; background: var(--primary);
    transform: scaleY(0); transform-origin: bottom;
    transition: transform 0.22s ease;
  }
  .portal-card:hover {
    background: var(--surface); border-color: rgba(255,193,7,0.5);
    transform: translateY(-2px);
    box-shadow: 0 6px 22px rgba(255,193,7,0.14);
  }
  .portal-card:hover::before { transform: scaleY(1); }

  .portal-card-icon {
    width: 34px; height: 34px;
    background: rgba(255,193,7,0.1); border-radius: 7px;
    display: flex; align-items: center; justify-content: center;
    transition: background 0.2s;
  }
  .portal-card:hover .portal-card-icon { background: rgba(255,193,7,0.22); }
  .portal-card-icon svg { width: 16px; height: 16px; color: var(--primary-dark); }

  .portal-card-name {
    font-size: 12.5px; font-weight: 800; color: var(--dark); line-height: 1.3;
  }
  .portal-card-sub {
    font-size: 10px; color: var(--text-muted); font-weight: 400; margin-top: 1px;
  }
  .portal-card-arrow {
    position: absolute; right: 12px; top: 50%;
    transform: translateY(-50%);
    color: var(--text-muted); opacity: 0.3;
    transition: all 0.2s;
  }
  .portal-card:hover .portal-card-arrow {
    opacity: 1; color: var(--primary-dark); right: 8px;
  }

  /* RIGHT FOOTER */
  .right-footer {
    padding: 16px 24px 22px;
    border-top: 1px solid var(--border);
  }
  .notice-box {
    background: linear-gradient(135deg, rgba(255,193,7,0.07), rgba(255,193,7,0.02));
    border: 1px solid rgba(255,193,7,0.2);
    border-radius: 8px; padding: 12px 14px;
    display: flex; gap: 10px; align-items: flex-start;
  }
  .notice-icon {
    width: 26px; height: 26px; background: var(--primary);
    border-radius: 50%; display: flex;
    align-items: center; justify-content: center;
    flex-shrink: 0; margin-top: 1px;
  }
  .notice-icon svg { width: 12px; height: 12px; color: var(--dark); }
  .notice-text { font-size: 11px; color: var(--text-muted); line-height: 1.65; }
  .notice-text strong {
    color: var(--dark); font-weight: 700;
    display: block; margin-bottom: 2px; font-size: 11.5px;
  }

  /* FOOTER */
  .footer {
    background: var(--dark); color: rgba(255,255,255,0.38);
    font-size: 11px; padding: 13px 40px;
    display: flex; align-items: center; justify-content: center; gap: 8px;
  }
  .footer .accent { color: var(--primary); }
  .footer .sep { color: rgba(255,255,255,0.12); margin: 0 4px; }

  @keyframes fadeUp { to { opacity: 1; transform: translateY(0); } }

  @media (max-width: 920px) {
    .hero { grid-template-columns: 1fr; }
    .hero-left { min-height: 75vh; }
    .hero-right { border-left: none; border-top: 2px solid var(--primary); }
    .stats-bar { bottom: 20px; left: 28px; right: 28px; }
    .header { padding: 12px 20px; }
    .topbar { padding: 7px 20px; }
    .hero-left-content { padding: 48px 32px 100px; }
  }
  @media (max-width: 500px) {
    .portal-row { grid-template-columns: 1fr; }
    .hero-actions { flex-direction: column; }
    .btn { justify-content: center; }
    .header-badge { display: none; }
    .stats-bar { display: none; }
  }
</style>
</head>
