<script>
  // Live datetime
  function updateDateTime() {
    const now = new Date();
    const opts = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    const date = now.toLocaleDateString('id-ID', opts);
    const time = now.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    const el = document.getElementById('datetime-display');
    if (el) el.textContent = date + ' • ' + time;
  }
  updateDateTime();
  setInterval(updateDateTime, 1000);

  // Count-up stats
  function countUp(el, target, duration) {
    const start = performance.now();
    const suffix = el.dataset.suffix || '';
    const update = (now) => {
      const progress = Math.min((now - start) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      el.textContent = Math.floor(eased * target) + suffix;
      if (progress < 1) requestAnimationFrame(update);
      else el.textContent = target + suffix;
    };
    setTimeout(() => requestAnimationFrame(update), 1100);
  }
  document.querySelectorAll('[data-target]').forEach(el => {
    countUp(el, parseInt(el.dataset.target), 1800);
  });

  // Tagline rotation
  const pills = document.querySelectorAll('.tagline-pill');
  let idx = 0;
  setInterval(() => {
    pills[idx].classList.remove('active');
    idx = (idx + 1) % pills.length;
    pills[idx].classList.add('active');
  }, 1600);

  // Portal card stagger entrance
  const cards = document.querySelectorAll('.portal-card');
  cards.forEach((card, i) => {
    setTimeout(() => {
      card.style.transition = 'opacity 0.45s ease, transform 0.45s ease, background 0.22s, border-color 0.22s, box-shadow 0.22s';
      card.classList.add('visible');
    }, 700 + i * 90);
  });
</script>
